"""Static pages: about, contact, privacy. Kept apart from build_site.py so the layout code stays readable."""
import html
import urllib.parse

e = html.escape


def pages(email, today, categories, newsletter_html=""):
    cats_li = "".join(f"<li>{e(v)}</li>" for v in categories.values())
    q = urllib.parse.quote
    gmail = lambda subj: ("https://mail.google.com/mail/?view=cm&fs=1&to=" + q(email) + "&su=" + q(subj))
    topics = [("📰", "اقتراح خبر أو موضوع", "هل لديك فكرة أو معلومة تستحق التغطية؟"),
              ("✏️", "طلب تصحيح", "لاحظت خطأً في مقال؟ أخبرنا برابطه."),
              ("🤝", "إعلانات وشراكات", "للتعاون الإعلاني والشراكات."),
              ("💡", "ملاحظة أو اقتراح", "رأيك يساعدنا على تحسين الجريدة.")]
    cards = "".join(
        f'<a class="ct-card" href="{e(gmail("نكسوس بريس - " + t))}" target="_blank" rel="noopener" data-mail="{e(t)}">'
        f'<span class="ct-ico">{i}</span><b>{e(t)}</b><small>{e(d)}</small></a>' for i, t, d in topics)

    about = f"""<p>مرحباً بك في <b>نكسوس بريس</b>، جريدة إلكترونية عربية تُعنى بتغطية أبرز أحداث العالم على مدار الساعة، وتقديمها للقارئ بلغة واضحة وسياق كافٍ يساعده على فهم ما وراء الخبر، وليس مجرد قراءة عنوانه.</p>
<h2>رسالتنا</h2><p>أن نقدّم للقارئ العربي خبراً مفهوماً وموثوقاً، يُعرض بدقة وبصياغة أصيلة، بعيداً عن الإثارة والتضليل.</p>
<h2>ماذا نغطي؟</h2><ul>{cats_li}</ul>
<h2>كيف نعمل؟</h2><p>نتابع كبرى الصحف والقنوات ووكالات الأنباء العالمية والعربية المعروفة، ونستخلص منها الوقائع المؤكدة، ثم نعيد عرضها بصياغتنا الخاصة مع إضافة الخلفية والسياق اللازمين. أما الأخبار المغربية فنختارها من القضايا الأكثر تداولاً في المغرب على محرك البحث Google (Google Trends)، ونعتمد في تغطيتها على المصادر المنشورة حولها. ونستعين بأدوات تقنية حديثة في إعداد المحتوى وتنظيمه ونشره. ونشير في أسفل كل مقال إلى المصادر التي اعتمدنا عليها، ولا ننسخ نصوص الآخرين.</p>
<h2>معاييرنا التحريرية</h2><ul>
<li><b>الدقة:</b> نعتمد على مصادر معروفة ولا ننشر معلومة لا سند لها.</li>
<li><b>الوضوح:</b> نفصل بين الخبر والتحليل، ونكتب بلغة سليمة ومباشرة.</li>
<li><b>الشفافية:</b> نذكر مصادرنا ونعلن عن أي تصحيح.</li>
<li><b>احترام الملكية الفكرية:</b> نعيد الصياغة ولا ننقل، ونستخدم صوراً توضيحية مولّدة خصيصاً للموقع.</li></ul>
<h2>خدمات للقارئ</h2><p>إضافةً إلى الأخبار، نوفّر خدمة <a href="weather.html">الطقس ومواقيت الصلاة</a> لأي مدينة في العالم، واستطلاعاً يومياً للرأي، ونشرة بريدية تصلك فيها آخر الأخبار.</p>
<h2>التصحيحات</h2><p>إذا لاحظت خطأً في أي مقال فراسلنا عبر صفحة <a href="contact.html">اتصل بنا</a>، وسنراجع الملاحظة ونصحح الخطأ بأسرع وقت.</p>
<h2>الإعلانات والتمويل</h2><p>قد يعرض الموقع إعلانات (مثل Google AdSense) للمساعدة في تغطية تكاليف التشغيل، ولا تؤثر الإعلانات على محتوانا التحريري. راجع <a href="privacy-policy.html">سياسة الخصوصية</a> لمعرفة كيفية التعامل مع البيانات.</p>
<h2>إخلاء المسؤولية</h2><p>المحتوى المنشور مخصص للإعلام والمعرفة العامة، ولا يُعد نصيحة قانونية أو مالية أو استثمارية أو طبية. نوصي بالرجوع إلى مختص قبل اتخاذ أي قرار بناءً على ما يرد في الموقع. مواقيت الصلاة وحالة الطقس معلومات تقريبية مصدرها خدمات خارجية، فيُرجى الاعتماد على الجهات الرسمية في بلدك عند الحاجة.</p>"""

    contact = f"""<p class="lead">يسعدنا تواصلك معنا. للاقتراحات وطلبات التصحيح والتعاون الإعلاني، اختر ما يناسبك:</p>
<div class="ct-main">
<div class="ct-mail"><span>📧 البريد الإلكتروني</span><a href="mailto:{e(email)}" dir="ltr" id="ct-email">{e(email)}</a></div>
<div class="ct-actions">
<a class="btn" href="{e(gmail('تواصل مع نكسوس بريس'))}" target="_blank" rel="noopener" data-mail="">فتح في Gmail</a>
<a class="btn alt" href="mailto:{e(email)}">تطبيق البريد</a>
<button class="btn alt" type="button" id="ct-copy" data-email="{e(email)}">نسخ العنوان</button>
</div></div>
<h2>اختر موضوع رسالتك</h2><div class="ct-grid">{cards}</div>
<h2>أو اكتب لنا مباشرة</h2>
<form id="contact-form" class="ct-form" data-email="{e(email)}" novalidate>
<div class="ct-row"><input name="name" placeholder="الاسم الكامل" required autocomplete="name"><input name="email" type="email" placeholder="بريدك الإلكتروني" required autocomplete="email"></div>
<input name="subject" placeholder="موضوع الرسالة" required>
<textarea name="message" rows="6" placeholder="نص الرسالة" required></textarea>
<input type="text" name="_honey" tabindex="-1" autocomplete="off" style="display:none">
<button class="btn" type="submit">إرسال الرسالة</button>
<p class="form-msg" id="ct-msg" role="status"></p></form>
<h2>متى نرد؟</h2><p>نحرص على الرد خلال أيام عمل قليلة. وإذا كانت رسالتك تخص تصحيح معلومة في مقال، فنرجو ذكر عنوان المقال ورابطه لنتمكن من المراجعة بسرعة.</p>
{newsletter_html}"""

    privacy = f"""<p>آخر تحديث: {today}</p>
<p>نحترم خصوصيتك في <b>نكسوس بريس</b>. توضح هذه الصفحة أي معلومات قد تُجمع عند زيارتك للموقع، وكيف نستخدمها، وما هي خياراتك.</p>
<h2>1. المعلومات التي قد نجمعها</h2>
<ul><li><b>بيانات تقنية تلقائية:</b> مثل عنوان IP ونوع المتصفح ونظام التشغيل والصفحات التي تزورها ووقت الزيارة، وتُسجَّل عادةً لدى مزودي الاستضافة والخدمات الخارجية الموضحة أدناه.</li>
<li><b>رسائل البريد:</b> إذا راسلتنا فسنحصل على اسمك وبريدك ومحتوى رسالتك، ونستخدمها للرد عليك فقط.</li>
<li><b>النشرة البريدية:</b> إذا اشتركت فسنحتفظ ببريدك الإلكتروني لإرسال الأخبار إليك، ويمكنك إلغاء الاشتراك في أي وقت بمراسلتنا.</li>
<li><b>التعليقات:</b> الاسم ونص التعليق (والبريد إن كتبته، ولا يُنشر) يُحفظان لدينا لأغراض المراجعة، ويُنشر الاسم والنص فقط بعد الموافقة.</li>
<li><b>الموقع الجغرافي (اختياري):</b> لا نطلب موقعك إلا إذا ضغطت زر «موقعي» في خدمة الطقس والصلاة، ولا نحتفظ به على خوادمنا.</li></ul>
<h2>2. كيف نستخدم المعلومات</h2><p>نستخدمها لتشغيل الموقع وتحسين أدائه وتجربة القراءة، وللرد على رسائلك، ولعرض الإعلانات، ولحماية الموقع من إساءة الاستخدام. نحن لا نبيع بياناتك الشخصية.</p>
<h2>3. التخزين المحلي وملفات تعريف الارتباط (Cookies)</h2><p>قد يستخدم الموقع وشركاؤه ملفات تعريف الارتباط والتخزين المحلي في متصفحك لحفظ تفضيلاتك (مثل لغة العرض والوضع الليلي والمدينة المختارة وتصويتك في الاستطلاع) ولأغراض الإعلانات والتحليلات. يمكنك حذفها أو منعها من إعدادات متصفحك، وقد لا تعمل بعض الميزات كما ينبغي إذا عطّلتها.</p>
<h2>4. الإعلانات وGoogle AdSense</h2>
<p>قد نستخدم خدمة Google AdSense لعرض الإعلانات. تستخدم Google وشركاؤها ملفات تعريف الارتباط (ومنها ملف DoubleClick) لعرض إعلانات استناداً إلى زياراتك السابقة لهذا الموقع أو لمواقع أخرى. وبفضل استخدام ملفات تعريف الارتباط الإعلانية تستطيع Google وشركاؤها عرض إعلانات مناسبة لك.</p>
<ul><li>يمكنك إلغاء الإعلانات المخصصة من <a href="https://adssettings.google.com" rel="noopener" target="_blank">إعدادات إعلانات Google</a>.</li>
<li>يمكنك أيضاً إلغاء استخدام ملفات تعريف الارتباط لدى بعض الجهات الإعلانية عبر <a href="https://www.aboutads.info" rel="noopener" target="_blank">aboutads.info</a>.</li>
<li>لمعرفة كيف تستخدم Google البيانات: <a href="https://policies.google.com/technologies/partner-sites" rel="noopener" target="_blank">سياسة Google للمواقع الشريكة</a>.</li></ul>
<p>إذا كنت في المنطقة الاقتصادية الأوروبية أو المملكة المتحدة أو سويسرا فقد تُعرض عليك أداة لإدارة الموافقة على ملفات تعريف الارتباط الإعلانية، ولك أن تقبل أو ترفض.</p>
<h2>5. خدمات الأطراف الثالثة</h2>
<ul><li><b>GitHub Pages:</b> استضافة الموقع، وقد تسجّل بيانات الزيارة التقنية.</li>
<li><b>Google Apps Script / Google Sheets:</b> استقبال التعليقات ورسائل «اتصل بنا» والاشتراك في النشرة.</li>
<li><b>Google Translate:</b> ترجمة الصفحات عند اختيارك الفرنسية أو الإنجليزية، ويُحمَّل فقط عند طلبك ذلك.</li>
<li><b>Google Fonts:</b> تحميل خط الموقع.</li>
<li><b>Open-Meteo:</b> بيانات الطقس والبحث عن المدن، وتُرسل إليها المدينة أو الإحداثيات التي تختارها فقط.</li>
<li><b>BigDataCloud:</b> تحويل إحداثياتك إلى اسم مدينة عند الضغط على «موقعي» فقط.</li>
<li><b>Aladhan:</b> حساب مواقيت الصلاة، وتُرسل إليها إحداثيات المدينة التي تختارها فقط.</li>
<li><b>CounterAPI:</b> حفظ عدد الأصوات في الاستطلاع اليومي، دون ربطها بهويتك.</li>
<li><b>Cloudinary:</b> تخزين صور المقالات وتسريع عرضها.</li>
<li><b>Amazon Associates:</b> بعض صفحات «عروض أمازون» تحتوي على روابط تابعة، وقد نحصل على عمولة من المشتريات المؤهلة دون تكلفة عليك.</li>
<li><b>روابط خارجية:</b> قد نشير إلى مصادر الأخبار؛ ولا نتحمل مسؤولية سياسات الخصوصية في تلك المواقع.</li></ul>
<h2>6. مدة الاحتفاظ بالبيانات</h2><p>نحتفظ بالرسائل البريدية مدة لازمة للرد والمتابعة، ثم نحذفها عند عدم الحاجة إليها. أما بيانات الخدمات الخارجية فتخضع لسياساتها.</p>
<h2>7. حقوقك</h2><p>يحق لك طلب الاطلاع على بياناتك الشخصية التي بحوزتنا أو تصحيحها أو حذفها، والاعتراض على معالجتها وفق القوانين المعمول بها، ومنها القانون المغربي رقم 09-08 المتعلق بحماية الأشخاص الذاتيين تجاه معالجة المعطيات ذات الطابع الشخصي، ولوائح حماية البيانات الأوروبية إن كانت تنطبق عليك. لممارسة هذه الحقوق راسلنا عبر <a href="contact.html">صفحة الاتصال</a>.</p>
<h2>8. حماية الأطفال</h2><p>الموقع غير موجه للأطفال دون 13 سنة، ولا نجمع بيانات عنهم عن قصد. إذا علمت أن طفلاً قدّم لنا بيانات فراسلنا لنحذفها.</p>
<h2>9. الأمان</h2><p>نتخذ إجراءات معقولة لحماية المعلومات، ومع ذلك لا توجد وسيلة نقل أو تخزين إلكتروني آمنة بنسبة 100%.</p>
<h2>10. تعديل هذه السياسة</h2><p>قد نحدّث هذه السياسة من وقت لآخر، وسيظهر تاريخ آخر تحديث في أعلى الصفحة. استمرارك في استخدام الموقع يعني موافقتك على النسخة المحدّثة.</p>
<h2>11. اتصل بنا</h2><p>لأي استفسار عن هذه السياسة راسلنا على: <a href="mailto:{e(email)}" dir="ltr">{e(email)}</a></p>"""

    return {"about.html": ("من نحن", about, ""), "contact.html": ("اتصل بنا", contact, "ct-page"),
            "privacy-policy.html": ("سياسة الخصوصية", privacy, "")}
